def feature(s):
    s = s or {}
    c = s.get('composition') or {}
    p = s.get('element_properties') or {}
    v = s.get('volume_per_atom_A3')
    if v is None or not isfinite(v) or v <= 0:
        return 0.0
    total = 0.0
    spheres = 0.0
    for el, x in c.items():
        if x is None or x <= 0:
            continue
        total += x
        r = (p.get(el) or {}).get('covalent_radius_A')
        if r is not None and isfinite(r) and r > 0:
            spheres += x * r ** 3
    if total <= 0:
        return 0.0
    return float(4.0 * pi * spheres / (3.0 * total * v))

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    n = len(sites)
    nearest = [0.0 for i in range(n)]
    for b in s.get('neighbors') or []:
        i = b.get('i')
        d = b.get('distance_A')
        if i is None or i < 0 or i >= n or d is None or not isfinite(d) or d <= 0:
            continue
        if nearest[i] == 0.0 or d < nearest[i]:
            nearest[i] = d
    vals = [d for d in nearest if d > 0]
    return float(sum(vals) / len(vals)) if vals else 0.0

def feature(s):
    s = s or {}
    n = len(s.get('sites') or [])
    nearest = [0.0 for i in range(n)]
    for b in s.get('neighbors') or []:
        i = b.get('i')
        d = b.get('distance_A')
        if i is None or i < 0 or i >= n or d is None or not isfinite(d) or d <= 0:
            continue
        if nearest[i] == 0.0 or d < nearest[i]:
            nearest[i] = d
    vals = [d for d in nearest if d > 0]
    if not vals:
        return 0.0
    mean = sum(vals) / len(vals)
    return float(sqrt(sum((d - mean) ** 2 for d in vals) / len(vals)) / mean)

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    p = s.get('element_properties') or {}
    n = len(sites)
    radii = [float((p.get((t or {}).get('element')) or {}).get('covalent_radius_A') or 0.0) for t in sites]
    occ = [max(0.0, float((t or {}).get('occupancy') if (t or {}).get('occupancy') is not None else 1.0)) for t in sites]
    coord = [0.0 for i in range(n)]
    for b in s.get('neighbors') or []:
        i = b.get('i')
        j = b.get('j')
        d = b.get('distance_A')
        if i is None or j is None or not (0 <= i < n and 0 <= j < n) or d is None or d <= 0 or not isfinite(d):
            continue
        if radii[i] <= 0 or radii[j] <= 0:
            continue
        x = d / (radii[i] + radii[j])
        if x <= 2.0:
            coord[i] += occ[j] / (1.0 + (x / 1.2) ** 12)
    z = sum(occ)
    return float(sum(occ[i] * coord[i] for i in range(n)) / z) if z > 0 else 0.0

